/**
 * Renders the M0 probe page templates (and small P6 tile images and the
 * plugin icon) from src/layout via src/render/svg.ts, and writes them as
 * base64 into src/assets/templates.generated.ts for the plugin to write to
 * MyStyle/ on the device.
 *
 *   npm run render-templates            # regenerate + write previews/
 *   npm run render-templates -- --check # fail if the generated file is stale
 *
 * PNGs are 8-bit RGB without alpha, at the exact page size (the format
 * Ink2Task uses for Manta templates). Fonts: Libre Franklin (OFL), loaded
 * from scripts/fonts only, so output doesn't depend on system fonts.
 */
import {createHash} from 'node:crypto';
import {mkdirSync, readFileSync, writeFileSync} from 'node:fs';
import {join, resolve} from 'node:path';
import {Resvg} from '@resvg/resvg-js';
import {PNG} from 'pngjs';
import {probePages, MANTA_PAGE} from '../src/layout/probe';
import {layoutToSvg, TEMPLATE_FONT_FAMILY} from '../src/render/svg';

const ROOT = resolve(__dirname, '..');
const FONT_DIR = join(ROOT, 'scripts', 'fonts');
const OUT_FILE = join(ROOT, 'src', 'assets', 'templates.generated.ts');
const ICON_FILE = join(ROOT, 'assets', 'icon.png');
const PREVIEW_DIR = join(ROOT, 'previews');

const FONT_FILES = [
  'LibreFranklin-Regular.ttf',
  'LibreFranklin-SemiBold.ttf',
  'LibreFranklin-Bold.ttf',
].map(f => join(FONT_DIR, f));

function rasterise(svg: string): Buffer {
  const resvg = new Resvg(svg, {
    fitTo: {mode: 'original'},
    font: {
      fontFiles: FONT_FILES,
      loadSystemFonts: false,
      defaultFontFamily: TEMPLATE_FONT_FAMILY,
    },
  });
  return resvg.render().asPng();
}

/** RGBA PNG (from resvg) → PNG with the given colour type, composited on white. */
function reencode(png: Buffer, colorType: 2 | 6): Buffer {
  const img = PNG.sync.read(png);
  if (colorType === 2) {
    const d = img.data;
    for (let i = 0; i < d.length; i += 4) {
      const a = d[i + 3] / 255;
      d[i] = Math.round(d[i] * a + 255 * (1 - a));
      d[i + 1] = Math.round(d[i + 1] * a + 255 * (1 - a));
      d[i + 2] = Math.round(d[i + 2] * a + 255 * (1 - a));
      d[i + 3] = 255;
    }
  }
  return PNG.sync.write(img, {
    colorType,
    inputColorType: 6,
    inputHasAlpha: true,
    deflateLevel: 9,
  });
}

function sha(buf: Buffer): string {
  return createHash('sha256').update(buf).digest('hex').slice(0, 10);
}

/** A 100×100 tile: grey fill, 4 px black border (the future Wordle tile look). */
function tileSvg(grey: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" shape-rendering="crispEdges">
<rect x="0" y="0" width="100" height="100" fill="${grey}"/>
<rect x="2" y="2" width="96" height="96" fill="none" stroke="#000000" stroke-width="4"/>
</svg>`;
}

/** 48×48 toolbar icon: a tiny crossword grid. Transparent background. */
function iconSvg(): string {
  const cells: string[] = [];
  const black = new Set(['0,2', '2,0', '1,1']);
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      const x = 6 + c * 12;
      const y = 6 + r * 12;
      cells.push(
        black.has(`${r},${c}`)
          ? `<rect x="${x}" y="${y}" width="12" height="12" fill="#000000"/>`
          : `<rect x="${x + 1}" y="${
              y + 1
            }" width="10" height="10" fill="none" stroke="#000000" stroke-width="2"/>`,
      );
    }
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" shape-rendering="crispEdges">
<rect x="5" y="5" width="38" height="38" fill="none" stroke="#000000" stroke-width="2"/>
${cells.join('\n')}
</svg>`;
}

interface Rendered {
  id: string;
  width: number;
  height: number;
  sha: string;
  png: Buffer;
}

function renderAll(): {
  pages: Rendered[];
  tiles: Record<string, Rendered>;
  icon: Buffer;
} {
  const pages = probePages(MANTA_PAGE).map(layout => {
    const png = reencode(rasterise(layoutToSvg(layout)), 2);
    return {
      id: layout.id,
      width: layout.size.width,
      height: layout.size.height,
      sha: sha(png),
      png,
    };
  });
  const tiles: Record<string, Rendered> = {};
  for (const [name, grey] of [
    ['dark', '#9d9d9d'],
    ['light', '#c9c9c9'],
  ] as const) {
    const png = reencode(rasterise(tileSvg(grey)), 2);
    tiles[name] = {
      id: `tile-${name}`,
      width: 100,
      height: 100,
      sha: sha(png),
      png,
    };
  }
  const icon = reencode(rasterise(iconSvg()), 6);
  return {pages, tiles, icon};
}

function generatedSource(
  pages: Rendered[],
  tiles: Record<string, Rendered>,
): string {
  const entry = (r: Rendered) =>
    `  {id: '${r.id}', width: ${r.width}, height: ${r.height}, sha: '${
      r.sha
    }', base64: '${r.png.toString('base64')}'}`;
  const version = sha(Buffer.from(pages.map(p => p.sha).join(',')));
  return `// Generated by scripts/render-templates.ts. Do not edit; run \`npm run render-templates\`.
/* eslint-disable */
export interface EmbeddedPng {
  id: string;
  width: number;
  height: number;
  /** First 10 hex chars of the PNG's SHA-256; part of the file name on the device. */
  sha: string;
  base64: string;
}

/** Changes whenever any probe template changes. */
export const PROBE_TEMPLATE_VERSION = '${version}';

/** Probe pages in page order (0-based page index = array index). */
export const PROBE_TEMPLATES: EmbeddedPng[] = [
${pages.map(entry).join(',\n')},
];

export const TILE_PNGS: {dark: EmbeddedPng; light: EmbeddedPng} = {
  dark: ${entry(tiles.dark).trim()},
  light: ${entry(tiles.light).trim()},
};
`;
}

function main(): void {
  const check = process.argv.includes('--check');
  const {pages, tiles, icon} = renderAll();
  const source = generatedSource(pages, tiles);

  if (check) {
    const current = readFileSync(OUT_FILE, 'utf8');
    const iconNow = readFileSync(ICON_FILE);
    if (current !== source || !iconNow.equals(icon)) {
      console.error(
        'Templates are stale: run `npm run render-templates` and commit the result.',
      );
      process.exit(1);
    }
    console.log('Templates are up to date.');
    return;
  }

  mkdirSync(join(ROOT, 'src', 'assets'), {recursive: true});
  writeFileSync(OUT_FILE, source);
  writeFileSync(ICON_FILE, icon);
  mkdirSync(PREVIEW_DIR, {recursive: true});
  for (const p of pages) {
    writeFileSync(join(PREVIEW_DIR, `${p.id}.png`), p.png);
  }
  for (const t of Object.values(tiles)) {
    writeFileSync(join(PREVIEW_DIR, `${t.id}.png`), t.png);
  }
  writeFileSync(join(PREVIEW_DIR, 'icon.png'), icon);
  for (const p of pages) {
    console.log(
      `${p.id}: ${p.width}×${p.height}, ${(p.png.length / 1024).toFixed(
        1,
      )} KB, sha ${p.sha}`,
    );
  }
  console.log(`Wrote ${OUT_FILE} and previews in ${PREVIEW_DIR}`);
}

main();
